import sys
def fonk1(a2,b2):
	return (a2-1) * (b2-1)
def fonk2(a,b5):
	return fonk4(a,b5)[0] == 1
def fonk3(b7,b8):
	a1 = 3
	while a1 < b8:
		if fonk2(a1,b7) and fonk2(a1,b8):
			return a1
		a1 = a1 + 2
def fonk4(a,b5):
	b3, b1 = 1, 0; b4, b6 = 0, 1
	while b5:
		b2 = a/b5
		b1, b3 = b3 - b2*b1, b1
		b6, b4 = b4 - b2*b6, b6
		a, b5 = b5, a % b5
	return a, b3, b4
def fonk5(a, m):
    g, b1, b6 = fonk4(a, m)
    if g != 1:
        raise Exception('No modular inverse')
    return b1%m
